// Value: protects=getStudentDirectoryMetrics queries only permitted columns, isolates each column's failure, windows attendance on Vietnam today-29..today,
// pages past 500 rows, counts a row repeated across offset pages once, and maps balance rows (null student skipped, null balance 0);
// fails_when=a forbidden column still queries its table, one failed column blanks the others or paints 0, the window uses the UTC date or 30 vs 31 days,
// pagination stops at the first page, a row shifted onto the next page is counted twice, or a null student_id row lands under "null";
// why_new=only the pure summaries had tests; the server loader (gating, isolation, window, paging) had none; seam=none (Supabase mocked at its client boundary);
// no_claim=does not prove the PostgREST embedded filter on session.session_date or RLS behave as assumed against the live schema
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const supabase = vi.hoisted(() => ({ from: vi.fn() }));

vi.mock("@/lib/supabase/server", () => ({
  createSupabaseServerClient: vi.fn(async () => ({ from: supabase.from })),
}));

import { getStudentDirectoryMetrics } from "@/features/students/data";

type PageResult = { data: unknown[] | null; error: unknown };
type TableSource = PageResult[] | (() => never);

/** Chainable PostgREST stand-in: filters record their args; `range()` resolves the next queued page. */
function tables(sources: Record<string, TableSource>) {
  const calls: Record<string, { method: string; args: unknown[] }[]> = {};

  supabase.from.mockImplementation((table: string) => {
    const source = sources[table];
    if (!source) throw new Error(`Unexpected table query: ${table}`);
    const log = (calls[table] ??= []);
    const builder: Record<string, unknown> = {};
    for (const method of ["select", "eq", "in", "gte", "lte", "order"]) {
      builder[method] = vi.fn((...args: unknown[]) => {
        log.push({ args, method });
        return builder;
      });
    }
    builder.range = vi.fn((...args: unknown[]) => {
      log.push({ args, method: "range" });
      if (typeof source === "function") return source();
      const page = source.shift() ?? { data: [], error: null };
      return Promise.resolve(page);
    });
    return builder;
  });

  return calls;
}

const allColumns = { includeAttendance: true, includeBalance: true, includeDebt: true };

beforeEach(() => {
  supabase.from.mockReset();
});

afterEach(() => {
  vi.useRealTimers();
});

describe("getStudentDirectoryMetrics", () => {
  it("never queries a forbidden column and keeps one column's failure from blanking or zeroing the others", async () => {
    tables({ student_session_balances: [{ data: [{ balance_sessions: 3, student_id: "a" }], error: null }] });

    const gated = await getStudentDirectoryMetrics({ includeAttendance: false, includeBalance: true, includeDebt: false });

    expect(supabase.from.mock.calls.map(([table]) => table)).toEqual(["student_session_balances"]);
    expect(gated).toEqual({
      attendanceRate: { reason: "forbidden", status: "unavailable" },
      balanceSessions: { byStudentId: { a: 3 }, status: "ready" },
      outstandingVnd: { reason: "forbidden", status: "unavailable" },
    });

    supabase.from.mockReset();
    tables({
      session_attendance: [{ data: null, error: { message: "permission denied for table session_attendance" } }],
      student_payment_requests: () => {
        throw new Error("fetch failed");
      },
      student_session_balances: [{ data: [{ balance_sessions: -2, student_id: "a" }], error: null }],
    });

    const isolated = await getStudentDirectoryMetrics(allColumns);

    expect(isolated).toEqual({
      attendanceRate: { reason: "failed", status: "unavailable" },
      balanceSessions: { byStudentId: { a: -2 }, status: "ready" },
      outstandingVnd: { reason: "failed", status: "unavailable" },
    });
  });

  it("windows attendance on the Vietnam date, pages past the first 500 rows, drops rows repeated across pages, and maps balance rows safely", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    // 01:30 on 13/10 in Vietnam, still 12/10 in UTC.
    vi.setSystemTime(new Date("2026-10-12T18:30:00.000Z"));

    const fullPage = Array.from({ length: 500 }, (_, index) => ({
      attendance_status: index < 10 ? "unexcused_absence" : "present",
      id: `att-${index}`,
      student_id: index < 250 ? "a" : "b",
    }));
    const calls = tables({
      session_attendance: [
        { data: fullPage, error: null },
        {
          data: [
            // att-0 shifted onto page 2 by an insert mid-read: counted once.
            fullPage[0],
            { attendance_status: "unexcused_absence", id: "att-c", student_id: "c" },
          ],
          error: null,
        },
      ],
      student_payment_requests: [
        {
          data: [
            // Partially paid never counts as overdue, however old (dashboard rule: pending only).
            { created_at: "2026-09-01T02:00:00+00:00", expected_amount_vnd: "1200000", id: "req-1", paid_amount_vnd: "200000", status: "partially_paid", student_id: "a" },
            { created_at: "2026-09-01T02:00:00+00:00", expected_amount_vnd: 500_000, id: "req-2", paid_amount_vnd: 0, status: "pending", student_id: null },
            // Pending for more than 14 days on the frozen clock: overdue.
            { created_at: "2026-09-20T02:00:00+00:00", expected_amount_vnd: 300_000, id: "req-3", paid_amount_vnd: 0, status: "pending", student_id: "d" },
          ],
          error: null,
        },
      ],
      student_session_balances: [
        {
          data: [
            { balance_sessions: 4, student_id: "a" },
            { balance_sessions: null, student_id: "b" },
            { balance_sessions: 9, student_id: null },
          ],
          error: null,
        },
      ],
    });

    const metrics = await getStudentDirectoryMetrics(allColumns);

    const attendance = calls.session_attendance;
    expect(attendance).toContainEqual({ args: ["session.session_date", "2026-09-14"], method: "gte" });
    expect(attendance).toContainEqual({ args: ["session.session_date", "2026-10-13"], method: "lte" });
    expect(attendance.filter((call) => call.method === "range").map((call) => call.args)).toEqual([
      [0, 499],
      [500, 999],
    ]);
    expect(calls.student_payment_requests).toContainEqual({ args: ["status", ["pending", "partially_paid"]], method: "in" });

    expect(metrics).toEqual({
      // a: 240 of 250 present; b: 250 of 250; c only exists on the second page.
      attendanceRate: { byStudentId: { a: 96, b: 100, c: 0 }, status: "ready" },
      balanceSessions: { byStudentId: { a: 4, b: 0 }, status: "ready" },
      outstandingVnd: {
        byStudentId: { a: { amountVnd: 1_000_000, overdue: false }, d: { amountVnd: 300_000, overdue: true } },
        status: "ready",
      },
    });
    expect(calls.student_payment_requests).toContainEqual({
      args: ["id, student_id, expected_amount_vnd, paid_amount_vnd, status, created_at"],
      method: "select",
    });
  });
});
